{"status": "success", "output": "from collections import deque


def _components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            result.append(cells)
    return result


def _shape(cells):
    top = min(r for r, _ in cells)
    left = min(c for _, c in cells)
    return frozenset((r - top, c - left) for r, c in cells)


def _distance(a, b):
    return min(abs(r-y) + abs(c-x) for r, c in a for y, x in b)


def transform(grid):
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda color: sum(row.count(color) for row in grid))
    objects = {color: _components(grid, color) for color in colors if color != bg}
    nine = objects.get(9, [])

    # Select the two top instruction components, excluding isolated palette
    # marker colors at the far top-right. The largest of those shapes is the
    # source; the other color indicates the output color.
    all_nonbg = [(c, p) for c, ps in objects.items() if c != 9 for p in ps]
    if not all_nonbg:
        return out
    # Find matching silhouettes between non-9 source motifs and target 9s.
    # The source is the motif nearest to the other instruction component; its
    # paired color is the color of that other component.
    matches = []
    for source_color, sources in objects.items():
        if source_color == 9:
            continue
        for source in sources:
            shape = _shape(source)
            if not any(_shape(t) == shape for t in nine):
                continue
            for key_color, keys in objects.items():
                if key_color in (source_color, 9):
                    continue
                for key in keys:
                    dist = _distance(source, key)
                    matches.append((dist, len(source), source_color, key_color, shape))
    if matches:
        # Prefer the tightly grouped primary diagrams over a lone distant marker.
        dist, _, _, replacement, shape = min(matches, key=lambda x: (x[0], -x[1]))
        if dist <= 10:
            for target in nine:
                if _shape(target) == shape:
                    for r, c in target:
                        out[r][c] = replacement
    return out


if __name__ == '__main__':
    pass
